def find_spam_folder(conn, fallback: str | None) -> str | None:
    """Ищет папку спама по флагу \\Junk/\\Spam в ответе LIST. Не находит — фолбэк."""
    try:
        typ, data = conn.list()
    except Exception:                                  # noqa: BLE001
        return fallback
    if typ != "OK":
        return fallback
    for raw in data or []:
        if raw is None:
            continue
        line = raw.decode("utf-8", "replace") if isinstance(raw, bytes) else raw
        if "\\Junk" in line or "\\Spam" in line:
            parts = line.rsplit('"', 2)
            if len(parts) >= 2 and parts[-2]:
                return parts[-2]
    return fallback


